import{_ as d,o,c as t,a2 as a}from"./chunks/framework.CuUVYbLV.js";const m=JSON.parse('{"title":"终止条件（已移除）","description":"声明式终止子系统的移除范围，以及 v1.9.0 仍生效的五类终止语义 — 硬上限、收敛退出、停滞升级、重试超时与级联取消","frontmatter":{"title":"终止条件（已移除）","description":"声明式终止子系统的移除范围，以及 v1.9.0 仍生效的五类终止语义 — 硬上限、收敛退出、停滞升级、重试超时与级联取消"},"headers":[],"relativePath":"04-Advanced/termination-conditions.md","filePath":"04-Advanced/termination-conditions.md"}'),c={name:"04-Advanced/termination-conditions.md"};function r(n,e,i,l,s,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="终止条件-termination-conditions-已移除" tabindex="-1">终止条件（Termination Conditions，已移除） <a class="header-anchor" href="#终止条件-termination-conditions-已移除" aria-label="Permalink to &quot;终止条件（Termination Conditions，已移除）&quot;">​</a></h1><p>终止条件曾是 <code>role.yaml</code> 的 <code>collaboration:</code> 块里的一节：用 <code>any_of</code> / <code>all_of</code> 组合循环退出规则。<strong>v1.8.0 起声明式终止子系统被整体移除</strong>，本页记录移除范围，以及 v1.9.0 仍然生效的终止语义。</p><blockquote><p>前置：<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>｜相关：<a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图（已移除）</a>、<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></p></blockquote><h2 id="移除了什么" tabindex="-1">移除了什么 <a class="header-anchor" href="#移除了什么" aria-label="Permalink to &quot;移除了什么&quot;">​</a></h2><p>v1.8.0 删除了下列终止相关对象，此后不再有任何声明式终止配置——终止只发生在命令式 <code>graph_*</code> 引擎内部：</p><table tabindex="0"><thead><tr><th>类别</th><th>被删除的对象</th></tr></thead><tbody><tr><td>配置字段</td><td><code>collaboration:</code> 的 <code>termination</code>（<code>any_of</code> / <code>all_of</code> 组合条件）</td></tr><tr><td>类型词汇表</td><td><code>TerminationDecl</code> / <code>TerminationCondition</code> / <code>LoopCondition</code> / <code>TerminationConfig</code></td></tr><tr><td>扩展点</td><td><code>termination_conditions</code></td></tr><tr><td>工具参数</td><td><code>graph_add_loop</code> 的 <code>termination</code> 参数</td></tr><tr><td>代码</td><td>v1 残留的 <code>termination*</code> 模块、异步收敛评估与终止配置解析器</td></tr></tbody></table><h2 id="现在仍存在的终止语义" tabindex="-1">现在仍存在的终止语义 <a class="header-anchor" href="#现在仍存在的终止语义" aria-label="Permalink to &quot;现在仍存在的终止语义&quot;">​</a></h2><p>五类机制取代了原来的声明式终止规则：</p><table tabindex="0"><thead><tr><th>机制</th><th>触发</th><th>结果</th></tr></thead><tbody><tr><td>循环组硬上限</td><td><code>graph_add_loop</code> 的 <code>max_traversals</code>（唯一必需上限，整数 ≥ 1）耗尽后仍收到 <code>revise_needed</code></td><td>节点升级为 escalate，携带 <code>{ reason: &quot;max_traversals exhausted&quot;, unresolved, traversals }</code></td></tr><tr><td>收敛退出</td><td>循环成员发出 <code>answer</code></td><td>循环自然结束，只走前向边，不消耗遍历次数，陈旧追踪器重置</td></tr><tr><td>停滞升级</td><td>连续 2 次（<code>CONSECUTIVE_STALE_THRESHOLD</code>）收敛输出完全相同</td><td>节点升级为 escalate，理由 <code>&quot;stuck&quot;</code>，不再消耗遍历次数</td></tr><tr><td>节点重试与超时</td><td><code>timeout_ms</code>（非负；<code>0</code> 表示关闭陈旧看门狗）到期，或节点 escalate 后重试预算未耗尽</td><td>超时按超时终态处理；有预算时节点重新标记为 <code>ready</code>，由引擎再次执行</td></tr><tr><td>级联取消</td><td><code>graph_cancel</code> 取消整图 / 单节点 / 整个循环组，<code>cascade: true</code> 时沿边传给全部下游</td><td>返回引擎实际取消的节点 id；循环组目标默认 <code>cascade: true</code>，裸 <code>node_id</code> 默认 <code>false</code></td></tr></tbody></table><p>生效的重试预算是 <code>budget.max_retries</code> 与任一入边／出边 <code>retry.max</code> 的较大值；节点顶级字段与 <code>budget</code> 内的同名字段等价，运行时只有一份。</p><p>引擎的静止裁决是第六类语义，表现为 <code>graph_status</code> 上的阶段变化而不是可配项：无 running / ready 且无 blocked、无 pending 时阶段推进 <code>complete</code>；仍有 blocked 时发出 blocked 终止事件，等待人工批准；仍有 pending 且永不可满足（死锁）时，pending 节点全部升级为 escalate（理由 <code>graph deadlock: no active upstream can satisfy pending node(s)</code>），随后进入 <code>complete</code>。</p><p><code>graph_add_loop</code> 的 <code>mode</code> 还有一个真实边界：<code>inherit</code> 是实际语义（轮次在同一份 engine state 内重新派发），<code>fresh</code> 不支持——传入即返回显式错误，需要会话隔离时改用每轮一张独立的图。级联取消是人工监控与干预控制，不用于 agent 自我取消；循环组内部另有一条取消路径——收敛节点的 join 失败时，仍在 pending 的上游节点被退役为 <code>cancelled → done</code>。</p><p>引擎内部如何裁决这些路径（静态判定、信号传播、重试入口）见<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a> — v0.x → v1.9.0 的破坏性变更清单与升级指南</li><li><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a> — 用 <code>graph_*</code> 工具编写现行多代理工作流</li><li><a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a> — 节点生命周期、信号传播与级联取消</li></ul>',15)])])}const _=d(c,[["render",r]]);export{m as __pageData,_ as default};
